import java.io.*;
import java.util.*;

public class CF819A_Variant4 {
    static int countUnique(int[] array, int startIdx, int endIdx) {
        boolean[] seenColors = new boolean[24];
        int uniqueCount = 0;
        for (int i = startIdx; i <= endIdx; i++) {
            int color = array[i];
            if (!seenColors[color]) {
                seenColors[color] = true;
                uniqueCount++;
            }
        }
        return uniqueCount;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        int l = Integer.parseInt(st.nextToken()) - 1;
        int r = Integer.parseInt(st.nextToken()) - 1;
        int totalAB = a + b;
        int repeatTimes = 4;
        int[] patternArr = new int[totalAB * repeatTimes];
        int shiftH = l / totalAB;
        l -= shiftH * totalAB;
        r -= shiftH * totalAB;
        int segmentSize = (r - l + 1) / totalAB;
        if (segmentSize > 2) r -= (segmentSize - 2) * totalAB;
        int deltaVal = Math.max(a - b, 1);
        for (int repIdx = 0; repIdx < repeatTimes; repIdx++) {
            for (int k = 0; k < a - deltaVal; k++)
                patternArr[totalAB * repIdx + k] = k;
            for (int k = 0; k < deltaVal; k++)
                patternArr[totalAB * repIdx + a - deltaVal + k] = (repIdx % 2 == 0) ? a - deltaVal + k : a + k;
        }
        int minColorsNeeded = a + a;
        for (int shiftAIdx = 1; shiftAIdx <= deltaVal; shiftAIdx++) {
            for (int k = 0; k < b; k++)
                patternArr[a + k] = patternArr[a - shiftAIdx];
            for (int shiftBIdx1 = 1; shiftBIdx1 <= deltaVal; shiftBIdx1++) {
                for (int k = 0; k < b; k++)
                    patternArr[totalAB + a + k] = patternArr[totalAB + a - shiftBIdx1];
                for (int shiftBIdx2 = 1; shiftBIdx2 <= deltaVal; shiftBIdx2++) {
                    for (int k = 0; k < b; k++)
                        patternArr[2 * totalAB + a + k] = patternArr[2 * totalAB + a - shiftBIdx2];
                    for (int shiftBIdx3 = 1; shiftBIdx3 <= deltaVal; shiftBIdx3++) {
                        for (int k = 0; k < b; k++)
                            patternArr[3 * totalAB + a + k] = patternArr[3 * totalAB + a - shiftBIdx3];
                        minColorsNeeded = Math.min(minColorsNeeded, countUnique(patternArr, l, r));
                    }
                }
            }
        }
        System.out.println(minColorsNeeded);
    }
}
